 <?php $__env->startSection('title','Pengguna'); ?> <?php $__env->startSection('content'); ?><div class="d-flex gap-2 mb-3"><form class="d-flex gap-2 flex-grow-1"><input class="form-control" name="search" value="<?php echo e(request('search')); ?>" placeholder="Cari nama/email"><select class="form-select" name="role"><option value="">Semua role</option><?php $__currentLoopData = ['admin','petugas','nasabah']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $x): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option <?php if(request('role')===$x): echo 'selected'; endif; ?>><?php echo e($x); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select><button class="btn btn-outline-secondary">Filter</button></form><a class="btn btn-success" href="<?php echo e(route('users.create')); ?>">+ Pengguna</a></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Nama</th><th>Email</th><th>Role</th><th>Aktif</th><th>Aksi</th></tr></thead><tbody><?php $__currentLoopData = $users; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $u): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><?php echo e($u->name); ?></td><td><?php echo e($u->email); ?></td><td><?php echo e($u->role); ?></td><td><?php echo e($u->is_active?'Ya':'Tidak'); ?></td><td><a class="btn btn-sm btn-warning" href="<?php echo e(route('users.edit',$u)); ?>">Edit</a><?php if($u->id!==auth()->id()): ?><form class="d-inline" method="post" action="<?php echo e(route('users.destroy',$u)); ?>"><?php echo csrf_field(); ?> <?php echo method_field('delete'); ?><button class="btn btn-sm btn-danger">Hapus</button></form><?php endif; ?></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div></div><div class="mt-3"><?php echo e($users->links()); ?></div><?php $__env->stopSection(); ?>
